from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone
import re


class ObjcliShowVersion(GenericUnixCommand):
    """Command objcli_show_version."""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = '/opt/trs/bin/objcli show_version'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_show_version(line)
            except ParsingDone:
                pass
        return super(ObjcliShowVersion, self).on_new_line(line, is_full_line)

    # actual HW Type      : 472959A
    _re_show_version = re.compile(r"^(?P<NAME>[^:]+):(?P<VALUE>[^:]+)$")

    def _parse_show_version(self, line):
        if self._regex_helper.search_compiled(ObjcliShowVersion._re_show_version, line):
            self.current_ret[self._regex_helper.group('NAME').rstrip()] = self._regex_helper.group('VALUE').lstrip()
            raise ParsingDone


